//! Roc platform host: a hyper-based HTTP server that dispatches requests to
//! handlers declared by the Roc app's `routes` entrypoint.
//!
//! `roc_platform_abi.rs` is generated by `roc glue` (see scripts/build-example.sh)
//! and must be regenerated whenever platform/main.roc changes.

#[allow(warnings)]
#[path = "roc_platform_abi.rs"]
mod abi;

mod server;

use core::ffi::c_void;
use std::ptr;
use std::sync::OnceLock;

/// Host context for the generated helper functions (RocStr construction etc.).
/// Compiled Roc code does not see this; it calls the `roc_*` symbols directly.
fn roc_host() -> &'static abi::RocHost {
    static HOST: OnceLock<abi::RocHost> = OnceLock::new();
    HOST.get_or_init(|| abi::make_roc_host(ptr::null_mut()))
}

// SAFETY: the default allocator/handler function pointers are stateless and
// thread-safe; env is null and never dereferenced.
unsafe impl Sync for abi::RocHost {}
unsafe impl Send for abi::RocHost {}

// ---------------------------------------------------------------------------
// Direct symbol ABI required by compiled/interpreted Roc code.
// ---------------------------------------------------------------------------

#[unsafe(no_mangle)]
pub extern "C" fn roc_alloc(length: usize, alignment: usize) -> *mut c_void {
    abi::DefaultAllocators::roc_alloc(ptr::null_mut(), length, alignment)
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_dealloc(ptr_: *mut c_void, alignment: usize) {
    abi::DefaultAllocators::roc_dealloc(ptr::null_mut(), ptr_, alignment)
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_realloc(
    ptr_: *mut c_void,
    new_length: usize,
    alignment: usize,
) -> *mut c_void {
    abi::DefaultAllocators::roc_realloc(ptr::null_mut(), ptr_, new_length, alignment)
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_dbg(bytes: *const u8, len: usize) {
    let message = unsafe { core::slice::from_raw_parts(bytes, len) };
    tracing::debug!(target: "roc", "{}", String::from_utf8_lossy(message));
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_expect_failed(bytes: *const u8, len: usize) {
    let message = unsafe { core::slice::from_raw_parts(bytes, len) };
    tracing::error!(target: "roc", "expect failed: {}", String::from_utf8_lossy(message));
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_crashed(bytes: *const u8, len: usize) {
    let message = unsafe { core::slice::from_raw_parts(bytes, len) };
    // Spike behavior: log and exit. The real failure model (catch -> 500)
    // lands with the router work.
    eprintln!("[ROC CRASHED] {}", String::from_utf8_lossy(message));
    std::process::exit(1);
}

// ---------------------------------------------------------------------------
// Route table.
// ---------------------------------------------------------------------------

/// A boxed Roc handler function. The underlying erased callable lives for the
/// whole process (the route list returned by `roc_routes` is intentionally
/// never released), so sharing the raw pointer across threads is sound as
/// long as invocation itself is thread-safe (verified by the stress spike).
#[derive(Clone, Copy)]
pub struct RocHandler(abi::RocErasedCallable);

unsafe impl Send for RocHandler {}
unsafe impl Sync for RocHandler {}

pub struct Route {
    pub method: String,
    pub path: String,
    pub handler: RocHandler,
}

/// Fetch the route table from the Roc app. The returned Roc list is leaked on
/// purpose: handlers must stay alive for the lifetime of the server.
fn load_routes() -> Vec<Route> {
    let roc_list = unsafe { abi::roc_routes() };
    roc_list
        .as_slice()
        .iter()
        .map(|entry| Route {
            method: String::from_utf8_lossy(entry.method.as_slice()).into_owned(),
            path: String::from_utf8_lossy(entry.path.as_slice()).into_owned(),
            handler: RocHandler(entry.handler),
        })
        .collect()
}

/// Invoke a boxed Roc handler through the erased-callable ABI.
///
/// Ownership: the args buffer's `RocStr` is consumed by the callee; the
/// returned `RocStr` is owned by us and released after copying out.
pub fn call_handler(handler: RocHandler, request: &str) -> String {
    #[repr(C)]
    struct Args {
        arg0: abi::RocStr,
    }

    let host = roc_host();
    let args = Args {
        arg0: abi::RocStr::from_slice(request.as_bytes(), host),
    };
    let mut ret = core::mem::MaybeUninit::<abi::RocStr>::uninit();
    unsafe {
        let payload = abi::roc_erased_callable_payload_ptr(handler.0);
        let capture = abi::roc_erased_callable_capture_ptr(handler.0);
        ((*payload).callable_fn_ptr)(
            host as *const abi::RocHost as *mut abi::RocHost,
            ret.as_mut_ptr() as *mut u8,
            &args as *const Args as *const u8,
            capture,
        );
        let result = ret.assume_init();
        let body = String::from_utf8_lossy(result.as_slice()).into_owned();
        result.decref(host);
        body
    }
}

// ---------------------------------------------------------------------------
// Hosted functions (effects available to Roc code).
// ---------------------------------------------------------------------------

/// Hosted symbol for `Host.now_ms!` — milliseconds since the Unix epoch.
#[unsafe(no_mangle)]
pub extern "C" fn roc_now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_millis() as u64)
        .unwrap_or(0)
}

/// Process entrypoint. The Roc-built executable links this static library and
/// starts here.
#[unsafe(no_mangle)]
pub extern "C" fn main(_argc: i32, _argv: *const *const u8) -> i32 {
    let routes = load_routes();
    server::run(routes)
}
